from itertools import combinations
from typing import Optional

def find_avoiding_coloring(n: int, k: int) -> Optional[set[tuple[int, int]]]:
    edges = list(combinations(range(n), 2))
    index = {e: i for i, e in enumerate(edges)}
    for mask in range(1 << len(edges)):
        good = True
        for vertices in combinations(range(n), k):
            colors = {(mask >> index[e]) & 1 for e in combinations(vertices, 2)}
            if len(colors) == 1:
                good = False
                break
        if good:
            return {e for i, e in enumerate(edges) if (mask >> i) & 1}
    return None

from typing import Callable, Iterable, TypeVar
T = TypeVar("T")

def conditional_filter(outcomes: Iterable[T],
                       bad: Iterable[Callable[[T], bool]]) -> set[T]:
    live = set(outcomes)
    for predicate in bad:
        live = {x for x in live if not predicate(x)}
        if not live:
            raise ValueError("The strict-survival condition failed")
    return live

def balanced_turan_edges(m: int) -> list[tuple[int, int]]:
    if m < 0:
        raise ValueError("m must be nonnegative")
    return [(u, v) for u in range(m) for v in range(m, 2*m)]

